function useLoop(VALUE: Animated.Value, running: boolean, duration: number) {
  useEffect(() => {
    if (!running) {
      VALUE.setValue(0);
      return;
    }
    const loop = Animated.loop(
      Animated.timing(VALUE, { toValue: 1, duration, easing: Easing.out(Easing.quad), useNativeDriver: motion.native }),
    );
    loop.start();
    return () => loop.stop();
  }, [running]);
}
